const slides=[...document.querySelectorAll('.slide')];const progress=document.getElementById('progress');let current=0;function show(i){current=(i+slides.length)%slides.length;slides.forEach((s,idx)=>s.classList.toggle('active',idx===current));progress.style.width=((current+1)/slides.length*100)+'%';}document.getElementById('prev').onclick=()=>show(current-1);document.getElementById('next').onclick=()=>show(current+1);document.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key===' ')show(current+1);if(e.key==='ArrowLeft')show(current-1);});show(0);